def die(msg, wrote=False):
    print(f"\n✗ {msg}" + ("" if wrote else "\nNothing was written."))
    sys.exit(1)


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    flags = {a for a in sys.argv[1:] if a.startswith("--")}
    root = os.path.abspath(args[0] if args else os.getcwd())
    if not (os.path.isdir(os.path.join(root, "backend", "app"))
            and os.path.isdir(os.path.join(root, "frontend", "src"))):
        die(f"{root} is not the scalp-app repo root (expected backend/app and frontend/src)")
    print(f"── {FENCE} → {root}  (python {sys.version.split()[0]})")

    # ── preflight ──
    writes = list(EDITS) + list(NEW_FILES)
    js = [r for r in writes if r.endswith((".js", ".jsx", ".ts", ".tsx"))]
    if js:
        die(f"internal: JS/JSX in the write set {js} — this patch must not touch the frontend")
    for rel in EDITS:
        p = os.path.join(root, rel)
        if not os.path.isfile(p):
            die(f"missing {rel}")
        txt = open(p, encoding="utf-8").read()
        if FENCE in txt:
            die(f"{rel} already carries {FENCE} — already applied")
        for parent in PARENTS.get(rel, []):
            if parent not in txt:
                die(f"{rel} lacks parent fence {parent} — pull the latest main first")
    for rel in NEW_FILES:
        if os.path.exists(os.path.join(root, rel)):
            die(f"{rel} already exists — already applied, or hand-placed? "
                f"(remove it and run ONLY this script)")
    for m in MIRRORS:
        for rel in writes:
            mp = os.path.join(root, m, rel)
            if os.path.isfile(mp) and FENCE in open(mp, encoding="utf-8").read():
                die(f"mirror {m}/{rel} already carries {FENCE} — mixed state; "
                    f"rebuild the mirror (build-scalp.sh) or restore it first")
    if "--allow-dirty" not in flags and os.path.isdir(os.path.join(root, ".git")):
        try:
            st = subprocess.run(["git", "status", "--porcelain", "--"] + writes, cwd=root,
                                capture_output=True, text=True, timeout=30).stdout
        except Exception as e:
            st = ""
            print(f"  (git status unavailable: {e!r} — continuing)")
        dirty = [ln for ln in st.splitlines() if ln[:2].strip()]
        if dirty:
            die("uncommitted changes in target files (commit/stash, or pass --allow-dirty):\n  "
                + "\n  ".join(dirty))

    staged = {}
    for rel, edits in EDITS.items():
        txt = open(os.path.join(root, rel), encoding="utf-8").read()
        for i, (old, new) in enumerate(edits, 1):
            n = txt.count(old)
            if n != 1:
                die(f"{rel}: anchor {i}/{len(edits)} found {n}× (expected 1):\n{old[:300]}")
            txt = txt.replace(old, new)
        staged[rel] = txt
    for rel, txt in list(staged.items()) + list(NEW_FILES.items()):
        if rel.endswith(".py"):
            try:
                compile(txt, rel, "exec")
            except SyntaxError as e:
                die(f"{rel} does not compile after staging (python {sys.version.split()[0]}): {e}")
    print(f"  preflight ok — {sum(len(e) for e in EDITS.values())} anchored edits in "
          f"{len(EDITS)} files, {len(NEW_FILES)} new files, no JSX/JS (CRA lint: nothing to lint)")

    # ── write ──
    touched = []          # (path, backup or None)

    def write(path, txt):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        bak = None
        if os.path.exists(path):
            bak = f"{path}.bak-{FENCE}"
            shutil.copy2(path, bak)
        touched.append((path, bak))
        with open(path, "w", encoding="utf-8") as f:
            f.write(txt)

    def rollback(why):
        for path, bak in reversed(touched):
            try:
                if bak:
                    shutil.copy2(bak, path)
                    os.remove(bak)
                elif os.path.exists(path):
                    os.remove(path)
            except Exception as e:
                print(f"  !! could not restore {path}: {e!r}")
        for d in ("tools/vet", "tools"):
            dp = os.path.join(root, d)
            if os.path.isdir(dp) and not os.listdir(dp):
                os.rmdir(dp)
        die(f"{why}\nEvery file it touched was restored.", wrote=True)

    for rel, txt in list(staged.items()) + list(NEW_FILES.items()):
        write(os.path.join(root, rel), txt)
        print(f"  wrote {rel}")
        for m in MIRRORS:
            if os.path.isdir(os.path.join(root, m, rel.split("/")[0])):
                write(os.path.join(root, m, rel), txt)
                print(f"    mirrored → {m}/{rel}")

    if "--skip-tests" in flags:
        print("\n  --skip-tests: suites not run")
    else:
        be = os.path.join(root, "backend")
        env = dict(os.environ, PYTHONPATH=be)
        for suite in SUITES:
            if not os.path.isfile(os.path.join(be, suite)):
                rollback(f"suite {suite} not found — tree differs from expected main")
            print(f"── {suite}")
            try:
                r = subprocess.run([sys.executable, suite], cwd=be, env=env,
                                   capture_output=True, text=True, timeout=1800)
            except subprocess.TimeoutExpired:
                rollback(f"{suite} timed out")
            tail = "\n".join((r.stdout or "").strip().splitlines()[-1:])
            print("   " + tail)
            if r.returncode != 0:
                print("\n".join(l for l in (r.stdout + r.stderr).splitlines()
                                if "FAIL" in l or "Error" in l or "Traceback" in l)[-3000:])
                rollback(f"{suite} failed")
        cun = os.path.join(root, "check_undefined_names.py")
        if os.path.isfile(cun):
            print("── check_undefined_names.py")
            r = subprocess.run([sys.executable, cun], cwd=root, capture_output=True, text=True)
            print("   " + ((r.stdout or "").strip().splitlines() or [""])[-1])
            if r.returncode != 0 and "pyflakes is not installed" in (r.stdout + r.stderr):
                print("   ⚠ pyflakes not installed — undefined-name gate SKIPPED "
                      "(pip3 install pyflakes; the patch was pyflakes-clean when built)")
            elif r.returncode != 0:
                print((r.stdout + r.stderr)[-2000:])
                rollback("check_undefined_names.py failed")
    print(f"\n✓ {FENCE} applied. Backups: *.bak-{FENCE}")
    print("  Next: ./desktop/build-scalp.sh backend")
    print("  Seal in both wing modes (read-only, corpus on this machine):")
    print("    PYTHONPATH=backend python3 tools/vet/vet_wing_mode_compare.py --seal "
          "--csv /tmp/vet_wing_modes.csv")
    print("  First live session: grep the audit log for '[VET] armed' (wing_search=90 band=(…)) "
          "and '[VET][WING_FAR]'.")


if __name__ == "__main__":
    main()
